div class="pagination-wrap">{{ $testimonies->links() }}</div><style>.testimony-hero{display:grid;align-items:end;min-height:330px;padding:clamp(34px,7vw,80px);border-radius:28px;background:linear-gradient(135deg,color-mix(in srgb,var(--chrome) 92%,var(--surface)),color-mix(in srgb,var(--action) 55%,var(--surface)));color:var(--surface)}.testimony-hero p{font-size:.72rem;font-weight:850;letter-spacing:.16em}.testimony-hero h1{margin:12px 0;font-size:clamp(2.7rem,7vw,6rem);line-height:.92;letter-spacing:-.06em}.testimony-hero h1 em{font-family:Georgia,serif;font-weight:400}.testimony-hero span{max-width:600px;display:block;line-height:1.7;color:color-mix(in srgb,var(--surface) 78%,transparent)}.testimony-filters{display:flex;gap:8px;overflow:auto;padding:24px 2px}.testimony-filters a{white-space:nowrap;padding:9px 14px;border:1px solid var(--line);border-radius:999px;color:var(--muted);font-size:.76rem;font-weight:750}.testimony-filters a.active{background:var(--text);color:var(--surface);border-color:var(--text)}.testimony-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.testimony-grid article{overflow:hidden;border:1px solid var(--line);border-radius:20px;background:var(--surface);box-shadow:var(--shadow-sm)}.testimony-grid article.featured{grid-column:span 2}.testimony-image{display:block;aspect-ratio:16/9;overflow:hidden}.testimony-image img{width:100%;height:100%;object-fit:cover}.testimony-card-body{display:grid;gap:14px;padding:22px}.testimony-meta,.testimony-card-body footer{display:flex;align-items:center;gap:10px}.testimony-meta{justify-content:space-between;color:var(--muted);font-size:.72rem}.testimony-meta span{color:var(--action)}.testimony-card-body h2,.testimony-card-body p{margin:0}.testimony-card-body p{color:var(--muted);line-height:1.7}.testimony-card-body footer{border-top:1px solid var(--line);padding-top:15px;font-size:.74rem}.testimony-card-body footer>a{margin-left:auto;color:var(--action);font-weight:800}.testimony-avatar,.testimony-avatar-image{display:grid;width:30px;height:30px;place-items:center;border-radius:50%;background:color-mix(in srgb,var(--action) 13%,var(--surface));color:var(--action);font-weight:850}.testimony-avatar-image{object-fit:cover}.testimony-empty{grid-column:1/-1;text-align:center;padding:70px;border:1px dashed var(--line);border-radius:22px}@media(max-width:900px){.testimony-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:620px){.testimony-grid{grid-template-columns:1fr}.testimony-grid article.featured{grid-column:auto}}</style></x-layouts.public>
